from pathlib import Path
BASE=Path('/Users/pss/orca/workspaces/today_/problem_make/.qa-artifacts/math-type-audit-20261018')
OUT=Path(__file__).parent
units={u['id']:u for u in json.loads((BASE/'units.json').read_text())}
PATTERNS=[
 ('elem',re.compile(r'^engine-elem:([^|]+)\|([^|]+)\|([^|]+)\|f([^|]+)\|(단답형|객관식)\|s(-?\d+)$')),
 ('mid',re.compile(r'^engine-mid:(.+)\|s(-?\d+)\|v(\d+)\|(단답형|객관식)$')),
 ('combo',re.compile(r'^engine-mid-combo:(.+)\|s(-?\d+)\|v(\d+)\|(단답형|객관식)$')),
]
MC=re.compile(r'^(.*)\n① ([^\n]*)\n② ([^\n]*)\n③ ([^\n]*)\n④ ([^\n]*)\n⑤ ([^\n]*)$',re.S)
MARKS='①②③④⑤'
def digest(x):
 return hashlib.sha256(x.encode()).hexdigest()
def jd(x):
 return digest(json.dumps(x,ensure_ascii=False,separators=(',',':'),sort_keys=True))
def key_of(ext):
 if not ext:return None
 for ns,pat in PATTERNS:
  m=pat.fullmatch(ext)
  if m:
   g=m.groups()
   if ns=='elem':return ns,'engine-elem:'+ '|'.join(g[:4])+'|s'+g[-1],g[-2]
   return ns,ext.rsplit('|',1)[0],g[-1]
 return None
rows=collections.Counter(); namespace=collections.Counter(); unparsed=collections.Counter(); unparsed_examples={}
groups=collections.defaultdict(list); all_solo=[]; h=hashlib.sha256(); ids=set(); codes=set(); duplicate_ids=0; duplicate_codes=0
per_grade=collections.defaultdict(collections.Counter); per_unit=collections.defaultdict(collections.Counter); per_source=collections.defaultdict(collections.Counter)
for raw in (BASE/'snapshot.jsonl').open('rb'):
 h.update(raw); r=json.loads(raw)
 duplicate_ids+=r['id'] in ids; ids.add(r['id']); duplicate_codes+=r['problemCode'] in codes; codes.add(r['problemCode'])
 ns=(r.get('externalId') or '').split(':')[0] or '(null)'
 if ':' not in (r.get('externalId') or ''):ns='(no-colon)' if r.get('externalId') else '(null)'
 namespace[ns]+=1
 grade=units.get(r['unitId'],{}).get('grade','(unknown)')
 for c in [rows,per_grade[grade],per_unit[r['unitId']],per_source[r['source']]]:
  c['rows']+=1;c['eligibleRows']+=int(r['eligible']);c['rows:'+str(r['questionType'])]+=1
  c['eligibleRows:'+str(r['questionType'])]+=int(r['eligible'])
 parsed=key_of(r.get('externalId'))
 content=r['content']; answer=r['answer']; match=MC.fullmatch(content)
 if r['questionType']=='객관식' and answer.strip() in MARKS and match:
  stem=match[1].rstrip(); selected=match[MARKS.index(answer.strip())+2]
  terminal=True
 else:stem=content.rstrip();selected=answer.strip();terminal=False
 meta={k:r.get(k) for k in ['unitId','source','familyKey','difficulty','problemType','originProblemId','sourceMaterialId']}
 figs={k:r.get(k) for k in ['figureSvg','figureUrls','figureDims','figureSourceMm','choiceFigureIndex','figureSource']}
 item={k:r.get(k) for k in ['id','problemCode','externalId','unitId','source','questionType','familyKey','difficulty','eligible']}
 item.update(grade=grade,metaDigest=jd(meta),stemDigest=digest(stem),answerDigest=digest(selected.strip()),solutionDigest=jd(r['solution']),figureDigest=jd(figs),terminalFiveChoice=terminal,choiceAnswer=answer.strip() in MARKS)
 if parsed:
  group_ns,key,suffix=parsed; item.update(suffix=suffix,namespace=group_ns);groups[key].append(item)
 else:
  unparsed[ns]+=1
  if ns not in unparsed_examples:unparsed_examples[ns]=r.get('externalId')
  all_solo.append(item)
verified=[]; rejected=[]; singles=[]; group_shapes=collections.Counter(); pairs_by_ns=collections.defaultdict(collections.Counter); eligibility_shapes=collections.Counter()
for key,members in sorted(groups.items()):
 shape=' + '.join(sorted(x['questionType'] for x in members));group_shapes[shape]+=1
 sa=[x for x in members if x['questionType']=='단답형'];mc=[x for x in members if x['questionType']=='객관식']
 if len(members)==1:singles.extend(members);continue
 reasons=[]
 if len(members)!=2 or len(sa)!=1 or len(mc)!=1:reasons.append('not-exactly-one-SA-one-MC')
 if any(x['suffix']!=x['questionType'] for x in members):reasons.append('external-format-column-disagree')
 if not reasons:
  a,b=sa[0],mc[0]
  if not b['terminalFiveChoice']:reasons.append('MC-not-terminal-five-lines-single-circled-answer')
  if a['choiceAnswer']:reasons.append('SA-answer-is-choice')
  for col in ['metaDigest','stemDigest','answerDigest','solutionDigest','figureDigest']:
   if a[col]!=b[col]:reasons.append(col+'-mismatch')
 if reasons:
  rejected.append({'key':key,'reasons':reasons,'members':members})
 else:
  pair={'key':key,'namespace':sa[0]['namespace'],'members':members};verified.append(pair)
  for c in [rows,per_grade[sa[0]['grade']],per_unit[sa[0]['unitId']],per_source[sa[0]['source']]]:
   c['verifiedPairs']+=1;c['eligiblePairReductions']+=int(sa[0]['eligible'] and mc[0]['eligible'])
  pairs_by_ns[sa[0]['namespace']]['pairs']+=1;pairs_by_ns[sa[0]['namespace']]['eligiblePairReductions']+=int(sa[0]['eligible'] and mc[0]['eligible'])
  eligibility_shapes[f"SA:{sa[0]['eligible']} MC:{mc[0]['eligible']}"]+=1
for c in [rows,*per_grade.values(),*per_unit.values(),*per_source.values()]:
 c['conservativeLogicalQuestions']=c['rows']-c['verifiedPairs'];c['conservativeEligibleQuestions']=c['eligibleRows']-c['eligiblePairReductions']
reason_counts=collections.Counter(reason for x in rejected for reason in x['reasons'])
manifest=OUT/'verified-pairs.jsonl'
with manifest.open('w') as f:
 for pair in verified:f.write(json.dumps(pair,ensure_ascii=False,separators=(',',':'))+'\n')
