rejected_path.write_text(json.dumps(rejected,ensure_ascii=False,indent=2)+'\n')
summary={
 'measuredAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'readOnly':True,'source':'immutable-snapshot-only-no-database',
 'snapshot':{'path':str(BASE/'snapshot.jsonl'),'sha256':h.hexdigest(),'meta':json.loads((BASE/'snapshot-meta.json').read_text()),'uniqueIds':len(ids),'uniqueCodes':len(codes),'duplicateIds':duplicate_ids,'duplicateCodes':duplicate_codes},
 'policy':'Only exact accepted engine external key SA/MC pairs plus matching metadata, base stem, answer selected by MC, solution and complete figure payload digests; every unproven row remains singleton.',
 'totals':rows,'namespaces':namespace,'parsedExternalGroups':len(groups),'parsedRows':sum(map(len,groups.values())),
 'parseGroupShapes':group_shapes,'unparsedNamespaces':unparsed,'unparsedExamples':unparsed_examples,
 'verifiedByNamespace':pairs_by_ns,'eligibilityShapes':eligibility_shapes,
 'rejectedGroups':len(rejected),'rejectedRows':sum(len(x['members']) for x in rejected),'rejectedReasons':reason_counts,
 'keyOnlyProjectionNotAccepted':{'allGroups':len(groups)+len(all_solo),'eligibleGroups':sum(any(x['eligible'] for x in g) for g in groups.values())+sum(x['eligible'] for x in all_solo)},
 'perGrade':per_grade,'perSource':per_source,'perUnit':{k:dict(v,grade=units[k]['grade'],chapter=units[k]['chapter'],section=units[k]['section']) for k,v in per_unit.items()},
 'manifest':{'privatePath':str(manifest.resolve()),'sha256':hashlib.sha256(manifest.read_bytes()).hexdigest(),'groups':len(verified)},
 'rejected':rejected,'verifiedExamples':verified[:8]
}
(OUT/'summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({k:summary[k] for k in ['totals','parsedExternalGroups','parsedRows','parseGroupShapes','unparsedNamespaces','unparsedExamples','verifiedByNamespace','eligibilityShapes','rejectedGroups','rejectedReasons','keyOnlyProjectionNotAccepted','perGrade']},ensure_ascii=False,indent=2))
